    34  // This is a Natural Cubic Spline. The second derivative at curve ends are zero.
    35  // See https://en.wikipedia.org/wiki/Spline_(mathematics)
    36  // section "Algorithm for computing natural cubic splines"
    37
    38  template <typename T = ushort16,
    39            typename = std::enable_if_t<std::is_arithmetic<T>::value>>
    40  class Spline final {
    41  public:
    42    using value_type = T;
    43
    44    // These are the constant factors for each segment of the curve.
    45    // Each segment i will have the formula:
    46    // f(x) = a[i] + b[i]*(x - x[i]) + c[i]*(x - x[i])^2 + d[i]*(x - x[i])^3
    47    struct Segment {
    48      double a;
    49      double b;
    50      double c;
    51      double d;
    52    };
    53
    54  private:
    55    int num_coords;
    56    int num_segments;
    57
    58    std::vector<int> xCp;
    59    std::vector<Segment> segments;
    60
    61    void prepare() {
    62      // Extra values used during computation
    63      std::vector<double> h(num_segments);
    64      std::vector<double> alpha(num_segments);
    65      std::vector<double> mu(num_coords);
    66      std::vector<double> z(num_coords);
    67
    68      for (int i = 0; i < num_segments; i++)
    69        h[i] = xCp[i + 1] - xCp[i];
    70
    71      for (int i = 1; i < num_segments; i++) {
    72        Segment& sp = segments[i - 1];
    73        Segment& s = segments[i];
    74        Segment& sn = segments[i + 1];
    75
    76        alpha[i] = (3. / h[i]) * (sn.a - s.a) - (3. / h[i - 1]) * (s.a - sp.a);
    77      }
    78
    79      // The last element is nonsensical, and was only used to temporairly store
    80      // the y value (Segment::a) of last point, so drop that 'segment' now
    81      segments.pop_back();
    82
    83      mu[0] = z[0] = 0;
    84
    85      for (int i = 1; i < num_segments; i++) {
    86        const double l = 2 * (xCp[i + 1] - xCp[i - 1]) - (h[i - 1] * mu[i - 1]);
    87        mu[i] = h[i] / l;
    88        z[i] = (alpha[i] - h[i - 1] * z[i - 1]) / l;
    89      }
    90
    91      z.back() = segments.back().c = 0;
    92
    93      for (int i = num_segments - 1; i >= 0; i--) {
    94        Segment& s = segments[i];
    95        Segment& sn = segments[i + 1];
    96
    97        s.c = z[i] - mu[i] * sn.c;
    98        s.b = (sn.a - s.a) / h[i] - h[i] * (sn.c + 2 * s.c) / 3.;
    99        s.d = (sn.c - s.c) / (3. * h[i]);
   100      }
   101
   102      assert(static_cast<typename decltype(segments)::size_type>(num_segments) ==
   103             segments.size());
   104    }
