   106  public:
   107    explicit Spline(const std::vector<iPoint2D>& control_points) {
   108      assert(control_points.size() >= 2 &&
   109             "Need at least two points to interpolate between");
   110
   111      // Expect the X coords of the curve to start/end at the extreme values
   112      assert(control_points.front().x == 0);
   113      assert(control_points.back().x == 65535);
   114
   115      assert(std::adjacent_find(
   116                 control_points.cbegin(), control_points.cend(),
   117                 [](const iPoint2D& lhs, const iPoint2D& rhs) -> bool {
   118                   return std::greater_equal<>()(lhs.x, rhs.x);
   119                 }) == control_points.cend() &&
   120             "The X coordinates must all be strictly increasing");
   121
   122  #ifndef NDEBUG
   123      if (!std::is_floating_point<value_type>::value) {
   124        // The Y coords must be limited to the range of value_type
   125        std::for_each(control_points.cbegin(), control_points.cend(),
   126                      [](const iPoint2D& p) -> void {
   127                        assert(p.y >= std::numeric_limits<value_type>::min());
   128                        assert(p.y <= std::numeric_limits<value_type>::max());
   129                      });
   130      }
   131  #endif
   132
   133      num_coords = control_points.size();
   134      num_segments = num_coords - 1;
   135
   136      xCp.resize(num_coords);
   137      segments.resize(num_coords);
   138      for (int i = 0; i < num_coords; i++) {
   139        xCp[i] = control_points[i].x;
   140        segments[i].a = control_points[i].y;
   141      }
   142
   143      prepare();
   144    }
   145
   146    std::vector<Segment> getSegments() const { return segments; }
   147
   148    std::vector<value_type> calculateCurve() const {
   149      std::vector<value_type> curve(65536);
   150
   151      for (int i = 0; i < num_segments; i++) {
   152        const Segment& s = segments[i];
   153
   154        for (int x = xCp[i]; x <= xCp[i + 1]; x++) {
   155          double diff = x - xCp[i];
   156          double diff_2 = diff * diff;
   157          double diff_3 = diff * diff * diff;
   158
   159          curve[x] = s.a + s.b * diff + s.c * diff_2 + s.d * diff_3;
   160        }
   161      }
   162
   163      return curve;
   164    }
