   296  // This method defines a correction that compensates for the fact that
   297  // IIQ files may come from a camera with multiple (four, in this case)
   298  // sensors combined into a single "sensor."  Because the different
   299  // sensors may have slightly different responses, we need to multiply
   300  // the pixels in each by a correction factor to ensure that they blend
   301  // together smoothly.  The correction factor is not a single
   302  // multiplier, but a curve defined by seven control points.  Each
   303  // curve's control points share the same seven X-coordinates.
   304  void IiqDecoder::CorrectQuadrantMultipliersCombined(ByteStream data,
   305                                                      uint32 split_row,
   306                                                      uint32 split_col) {
   307    std::array<uint32, 9> shared_x_coords;
   308
   309    // Read the middle seven points from the file
   310    std::generate_n(std::next(shared_x_coords.begin()), 7,
   311                    [&data] { return data.getU32(); });
   312
   313    // All the curves include (0, 0) and (65535, 65535),
   314    // so the first and last points are predefined
   315    shared_x_coords.front() = 0;
   316    shared_x_coords.back() = 65535;
   317
   318    // Check that the middle coordinates make sense.
   319    if (std::adjacent_find(shared_x_coords.cbegin(), shared_x_coords.cend(),
   320                           std::greater_equal<>()) != shared_x_coords.cend())
   321      ThrowRDE("The X coordinates must all be strictly increasing");
   322
   323    std::array<std::array<std::vector<iPoint2D>, 2>, 2> control_points;
   324    for (auto& quadRow : control_points) {
   325      for (auto& quadrant : quadRow) {
   326        quadrant.reserve(9);
   327        quadrant.emplace_back(0, 0);
   328
   329        for (int i = 1; i < 8; i++) {
   330          // These multipliers are expressed in ten-thousandths in the
   331          // file
   332          const uint64 y_coord =
   333              (uint64(data.getU32()) * shared_x_coords[i]) / 10000ULL;
   334          if (y_coord > 65535)
   335            ThrowRDE("The Y coordinate %llu is too large", y_coord);
   336          quadrant.emplace_back(shared_x_coords[i], y_coord);
   337        }
   338
   339        quadrant.emplace_back(65535, 65535);
   340        assert(quadrant.size() == 9);
   341      }
   342    }
   343
   344    for (int quadRow = 0; quadRow < 2; quadRow++) {
   345      for (int quadCol = 0; quadCol < 2; quadCol++) {
   346        const Spline<> s(control_points[quadRow][quadCol]);
   347        const std::vector<ushort16> curve = s.calculateCurve();
   348
   349        int row_start = quadRow == 0 ? 0 : split_row;
   350        int row_end = quadRow == 0 ? split_row : mRaw->dim.y;
   351        int col_start = quadCol == 0 ? 0 : split_col;
   352        int col_end = quadCol == 0 ? split_col : mRaw->dim.x;
   353
   354        for (int row = row_start; row < row_end; row++) {
   355          auto* pixel =
   356              reinterpret_cast<ushort16*>(mRaw->getData(col_start, row));
   357          for (int col = col_start; col < col_end; col++, pixel++) {
   358            // This adjustment is expected to be made with the
   359            // black-level already subtracted from the pixel values.
   360            // Because this is kept as metadata and not subtracted at
   361            // this point, to make the correction work we subtract the
   362            // appropriate amount before indexing into the curve and
   363            // then add it back so that subtracting the black level
   364            // later will work as expected
   365            const ushort16 diff = *pixel < black_level ? *pixel : black_level;
   366            *pixel = curve[*pixel - diff] + diff;
   367          }
   368        }
   369      }
   370    }
   371  }
