   110    const DataBuffer db(buf, Endianness::little);
   111    ByteStream bs(db);
   112
   113    bs.skipBytes(4); // Phase One magic
   114    bs.skipBytes(4); // padding?
   115
   116    const auto origPos = bs.getPosition();
   117
   118    const uint32 entries_offset = bs.getU32();
   119
   120    bs.setPosition(entries_offset);
   121
   122    const uint32 entries_count = bs.getU32();
   123    bs.skipBytes(4); // ???
   124
   125    // this is how much is to be read for all the entries
   126    ByteStream es(bs.getStream(entries_count, 16));
   127
   128    bs.setPosition(origPos);
   129
   130    uint32 width = 0;
   131    uint32 height = 0;
   132    uint32 split_row = 0;
   133    uint32 split_col = 0;
   134
