   149        break;
   150      case 0x108:
   151        width = data;
   152        break;
   153      case 0x109:
   154        height = data;
   155        break;
   156      case 0x10f:
   157        raw_data = bs.getSubView(data, len);
   158        break;
   159      case 0x110:
   160        correction_meta_data = bs.getSubStream(data);
   161        break;
   162      case 0x21c:
   163        // they are not guaranteed to be sequential!
