    65  TiffRootIFDOwner TiffParser::parse(const Buffer& data) {
    66    ByteStream bs(data, 0);
    67    bs.setByteOrder(getTiffByteOrder(bs, 0, "TIFF header"));
    68    bs.skipBytes(2);
    69
    70    ushort16 magic = bs.getU16();
    71    if (magic != 42 && magic != 0x4f52 && magic != 0x5352 && magic != 0x55) // ORF has 0x4f52/0x5352, RW2 0x55 - Brillant!
    72      ThrowTPE("Not a TIFF file (magic 42)");
    73
    74    TiffRootIFDOwner root = std::make_unique<TiffRootIFD>(
    75        nullptr, nullptr, bs,
    76        UINT32_MAX); // tell TiffIFD constructur not to parse bs as IFD
    77
    78    NORangesSet<Buffer> ifds;
    79
    80    for (uint32 IFDOffset = bs.getU32(); IFDOffset;
    81         IFDOffset = root->getSubIFDs().back()->getNextIFD()) {
    82      root->add(std::make_unique<TiffIFD>(root.get(), &ifds, bs, IFDOffset));
    83    }
    84
    85    return root;
    86  }
