    43  void TiffIFD::parseIFDEntry(NORangesSet<Buffer>* ifds, ByteStream* bs) {
    44    assert(ifds);
    45
    46    TiffEntryOwner t;
    47
    48    auto origPos = bs->getPosition();
    49
    50    try {
    51      t = std::make_unique<TiffEntry>(this, bs);
    52    } catch (IOException&) { // Ignore unparsable entry
    53      // fix probably broken position due to interruption by exception
    54      // i.e. setting it to the next entry.
    55      bs->setPosition(origPos + 12);
    56      return;
    57    }
    58
    59    try {
    60      switch (t->tag) {
    61      case DNGPRIVATEDATA:
    62        add(parseDngPrivateData(ifds, t.get()));
    63        break;
    64
    65      case MAKERNOTE:
    66      case MAKERNOTE_ALT:
    67        add(parseMakerNote(ifds, t.get()));
    68        break;
    69
    70      case FUJI_RAW_IFD:
    71      case SUBIFDS:
    72      case EXIFIFDPOINTER:
    73        for (uint32 j = 0; j < t->count; j++)
    74          add(std::make_unique<TiffIFD>(this, ifds, *bs, t->getU32(j)));
    75        break;
    76
    77      default:
    78        add(move(t));
    79      }
    80    } catch (RawspeedException&) { // Unparsable private data are added as entries
    81      add(move(t));
    82    }
    83  }
