    87  TiffIFD::TiffIFD(TiffIFD* parent_, NORangesSet<Buffer>* ifds,
    88                   const DataBuffer& data, uint32 offset)
    89      : TiffIFD(parent_) {
    90    // see TiffParser::parse: UINT32_MAX is used to mark the "virtual" top level
    91    // TiffRootIFD in a tiff file
    92    if (offset == UINT32_MAX)
    93      return;
    94
    95    assert(ifds);
    96
    97    checkOverflow();
    98
    99    ByteStream bs(data);
   100    bs.setPosition(offset);
   101
   102    // Directory entries in this IFD
   103    auto numEntries = bs.getU16();
   104
   105    // 2 bytes for entry count
   106    // each entry is 12 bytes
   107    // 4-byte offset to the next IFD at the end
   108    const auto IFDFullSize = 2 + 4 + 12 * numEntries;
   109    const Buffer IFDBuf(data.getSubView(offset, IFDFullSize));
   110    if (!ifds->emplace(IFDBuf).second)
   111      ThrowTPE("Two IFD's overlap. Raw corrupt!");
   112
   113    for (uint32 i = 0; i < numEntries; i++)
   114      parseIFDEntry(ifds, &bs);
   115
   116    nextIFD = bs.getU32();
   117  }
