   100  bool __attribute__((pure)) TiffEntry::isInt() const {
   101    return type == TIFF_LONG || type == TIFF_SHORT || type == TIFF_BYTE;
   102  }
   103
   104  bool __attribute__((pure)) TiffEntry::isString() const {
   105    return type == TIFF_ASCII;
   106  }
