   108  bool __attribute__((pure)) TiffEntry::isFloat() const {
   109    switch (type) {
   110    case TIFF_FLOAT:
   111    case TIFF_DOUBLE:
   112    case TIFF_RATIONAL:
   113    case TIFF_SRATIONAL:
   114    case TIFF_LONG:
   115    case TIFF_SLONG:
   116    case TIFF_SHORT:
   117    case TIFF_SSHORT:
   118      return true;
   119    default:
   120      return false;
   121    }
   122  }
