   124  uchar8 TiffEntry::getByte(uint32 index) const {
   125    if (type != TIFF_BYTE && type != TIFF_UNDEFINED)
   126      ThrowTPE("Wrong type %u encountered. Expected Byte on 0x%x", type, tag);
   127
   128    return data.peekByte(index);
   129  }
