   131  ushort16 TiffEntry::getU16(uint32 index) const {
   132    if (type != TIFF_SHORT && type != TIFF_UNDEFINED)
   133      ThrowTPE("Wrong type %u encountered. Expected Short or Undefined on 0x%x",
   134               type, tag);
