   139  short16 TiffEntry::getI16(uint32 index) const {
   140    if (type != TIFF_SSHORT && type != TIFF_UNDEFINED)
   141      ThrowTPE("Wrong type %u encountered. Expected Short or Undefined on 0x%x",
   142               type, tag);
