   147  uint32 TiffEntry::getU32(uint32 index) const {
   148    if (type == TIFF_SHORT)
   149      return getU16(index);
   150
   151    switch (type) {
   152    case TIFF_LONG:
   153    case TIFF_OFFSET:
   154    case TIFF_BYTE:
   155    case TIFF_UNDEFINED:
   156    case TIFF_RATIONAL:
   157    case TIFF_SRATIONAL:
   158      break;
   159    default:
   160      ThrowTPE("Wrong type %u encountered. Expected Long, Offset, Rational or "
   161               "Undefined on 0x%x",
   162               type, tag);
   163    }
   164
   165    return data.peek<uint32>(index);
   166  }
   167
   168  int32 TiffEntry::getI32(uint32 index) const {
   169    if (type == TIFF_SSHORT)
   170      return getI16(index);
   171    if (!(type == TIFF_SLONG || type == TIFF_UNDEFINED))
   172      ThrowTPE("Wrong type %u encountered. Expected SLong or Undefined on 0x%x",
   173               type, tag);
   174
   175    return data.peek<int32>(index);
   176  }
